{"kind":"tool","id":"eWcb_PujlGY","toolName":"write_file","input":{"path":"/tmp/indigo-shot.c","instructions":"Fix harness to build the window inside the application activate callback.","content":"#include <gtk/gtk.h>
#include <webkit/webkit.h>

#include "browser.h"

static void
snapshot_window(GtkWidget *window, const char *path)
{
    GdkPaintable *paintable = gtk_widget_paintable_new(window);
    GtkSnapshot *snapshot = gtk_snapshot_new();
    gdk_paintable_snapshot(paintable, snapshot, 1200, 800);
    GskRenderNode *node = gtk_snapshot_free_to_node(snapshot);
    cairo_surface_t *surface = cairo_image_surface_create(CAIRO_FORMAT_ARGB32, 1200, 800);
    cairo_t *cr = cairo_create(surface);
    gsk_render_node_draw(node, cr);
    cairo_surface_write_to_png(surface, path);
    cairo_destroy(cr);
    cairo_surface_destroy(surface);
    gsk_render_node_unref(node);
    g_object_unref(paintable);
    g_print("wrote %s\n", path);
}

static void
on_finished(WebKitWebView *view, WebKitLoadEvent event, gpointer window)
{
    (void)view;

    if (event != WEBKIT_LOAD_FINISHED)
        return;

    GtkWidget *content = gtk_window_get_child(GTK_WINDOW(window));
    GtkWidget *toolbar = gtk_widget_get_first_child(content);
    GtkWidget *notebook_widget = gtk_widget_get_next_sibling(toolbar);
    GtkWidget *page = gtk_notebook_get_nth_page(GTK_NOTEBOOK(notebook_widget), 0);
    GtkWidget *tab_label = gtk_notebook_get_tab_label(GTK_NOTEBOOK(notebook_widget), page);
    GtkWidget *inner = gtk_widget_get_first_child(tab_label);

    g_print("tab text: '%s'\n", gtk_label_get_text(GTK_LABEL(inner)));
    g_print("label width: %d tab width: %d\n",
            gtk_widget_get_width(inner), gtk_widget_get_width(tab_label));

    snapshot_window(window, "/tmp/indigo-before.png");

    gtk_window_destroy(GTK_WINDOW(window));
}

static void
on_activate(GtkApplication *app, gpointer user_data)
{
    (void)user_data;

    GtkWidget *window = browser_window_new(app);
    gtk_window_present(GTK_WINDOW(window));

    GtkWidget *content = gtk_window_get_child(GTK_WINDOW(window));
    GtkWidget *toolbar = gtk_widget_get_first_child(content);
    GtkWidget *notebook = gtk_widget_get_next_sibling(toolbar);
    GtkWidget *page = gtk_notebook_get_nth_page(GTK_NOTEBOOK(notebook), 0);
    g_signal_connect(page, "load-changed", G_CALLBACK(on_finished), window);
}

int
main(int argc, char **argv)
{
    setvbuf(stdout, NULL, _IONBF, 0);

    GtkApplication *app = gtk_application_new("com.projectindigo.Shot",
                                             G_APPLICATION_DEFAULT_FLAGS);
    g_signal_connect(app, "activate", G_CALLBACK(on_activate), NULL);
    int status = g_application_run(G_APPLICATION(app), argc, argv);
    g_object_unref(app);
    return status;
}
"}}


