static GtkWidget *make_tab(const char *text, int variant)
{
    GtkWidget *label = gtk_label_new(text);

    if (variant >= 1)
        gtk_label_set_ellipsize(GTK_LABEL(label), PANGO_ELLIPSIZE_END);
    if (variant == 1 || variant == 2)
        gtk_label_set_max_width_chars(GTK_LABEL(label), 24);
    if (variant == 2)
        gtk_label_set_width_chars(GTK_LABEL(label), 10);

    GtkWidget *box = gtk_box_new(GTK_ORIENTATION_HORIZONTAL, 4);
    gtk_box_append(GTK_BOX(box), label);
    gtk_box_append(GTK_BOX(box), gtk_button_new_from_icon_name("window-close-symbolic"));
    return box;
}

static gboolean
report(gpointer window)
{
    GtkWidget *notebook = gtk_window_get_child(GTK_WINDOW(window));
    for (int i = 0; i < 4; i++) {
        GtkWidget *page = gtk_notebook_get_nth_page(GTK_NOTEBOOK(notebook), i);
        GtkWidget *tab = gtk_notebook_get_tab_label(GTK_NOTEBOOK(notebook), page);
        GtkWidget *label = gtk_widget_get_first_child(tab);
        g_print("variant %d: label w=%d tab w=%d text='%s'\n", i,
                gtk_widget_get_width(label), gtk_widget_get_width(tab),
                gtk_label_get_text(GTK_LABEL(label)));
    }
    gtk_window_destroy(GTK_WINDOW(window));
    return G_SOURCE_REMOVE;
}

static void
on_activate(GtkApplication *app, gpointer unused)
{
    (void)unused;

    GtkWidget *window = gtk_application_window_new(app);
    gtk_window_set_default_size(GTK_WINDOW(window), 1100, 700);

    GtkWidget *notebook = gtk_notebook_new();
    gtk_notebook_set_scrollable(GTK_NOTEBOOK(notebook), TRUE);
    gtk_window_set_child(GTK_WINDOW(window), notebook);

    for (int i = 0; i < 4; i++)
        gtk_notebook_append_page(GTK_NOTEBOOK(notebook), gtk_label_new("page"),
                                 make_tab("Example Domain Title", i));

    gtk_window_present(GTK_WINDOW(window));
    g_timeout_add(500, report, window);
}

int
main(void)
{
    GtkApplication *app = gtk_application_new("com.test.Label", G_APPLICATION_DEFAULT_FLAGS);
    g_signal_connect(app, "activate", G_CALLBACK(on_activate), NULL);
