{"kind":"tool","id":"eWpdA28Qi4E","toolName":"write_file","input":{"path":"/tmp/shot-test.c","instructions":"Test offscreen widget-to-PNG rendering on a plain box.","content":"#include <gtk/gtk.h>

static gboolean
shot(gpointer widget)
{
    GtkWidget *w = widget;

    g_print("widget %s mapped=%d width=%d\n", G_OBJECT_TYPE_NAME(w),
            gtk_widget_get_mapped(w), gtk_widget_get_width(w));

    GdkPaintable *paintable = gtk_widget_paintable_new(w);
    int width = gtk_widget_get_width(w);
    int height = gtk_widget_get_height(w);

    GtkSnapshot *snapshot = gtk_snapshot_new();
    gdk_paintable_snapshot(paintable, snapshot, width, height);
    GskRenderNode *node = gtk_snapshot_free_to_node(snapshot);
    g_print("node=%p\n", (void *)node);

    if (node != NULL) {
        cairo_surface_t *surface = cairo_image_surface_create(CAIRO_FORMAT_ARGB32, width, height);
        cairo_t *cr = cairo_create(surface);
        gsk_render_node_draw(node, cr);
        cairo_surface_write_to_png(surface, "/tmp/widget-shot.png");
        cairo_destroy(cr);
        cairo_surface_destroy(surface);
        gsk_render_node_unref(node);
    }

    g_object_unref(paintable);
    gtk_window_destroy(GTK_WINDOW(gtk_widget_get_root(w)));
    return G_SOURCE_REMOVE;
}

static void
on_activate(GtkApplication *app, gpointer unused)
{
    (void)unused;

    GtkWidget *window = gtk_application_window_new(app);
    gtk_window_set_default_size(GTK_WINDOW(window), 600, 400);

    GtkWidget *box = gtk_box_new(GTK_ORIENTATION_VERTICAL, 6);
    gtk_widget_set_margin_start(box, 12);
    gtk_widget_set_margin_top(box, 12);
    gtk_box_append(GTK_BOX(box), gtk_label_new("Hello from the snapshot test"));
    gtk_box_append(GTK_BOX(box), gtk_button_new_with_label("A button"));
    gtk_window_set_child(GTK_WINDOW(window), box);
    gtk_window_present(GTK_WINDOW(window));

    g_timeout_add(500, shot, box);
}

int
main(void)
{
    setvbuf(stdout, NULL, _IONBF, 0);
    GtkApplication *app = gtk_application_new("com.test.Shot2", G_APPLICATION_DEFAULT_FLAGS);
    g_signal_connect(app, "activate", G_CALLBACK(on_activate), NULL);
    int status = g_application_run(G_APPLICATION(app), 0, NULL);
    g_object_unref(app);
    return status;
}
