#include <gtk/gtk.h>

#include "browser.h"

static GtkWidget *window;

static GtkWidget *
find_type(GtkWidget *widget, GType type)
{
    if (G_TYPE_CHECK_INSTANCE_TYPE(widget, type))
        return widget;

    for (GtkWidget *child = gtk_widget_get_first_child(widget); child != NULL;
         child = gtk_widget_get_next_sibling(child)) {
        GtkWidget *found = find_type(child, type);

        if (found != NULL)
            return found;
    }

    return NULL;
}

static GtkWidget *
find_button(GtkWidget *root, const char *text)
{
    GtkWidget *stack[512];
    int top = 0;

    stack[top++] = root;
    while (top > 0) {
        GtkWidget *widget = stack[--top];

        if (GTK_IS_LABEL(widget) &&
            g_strcmp0(gtk_label_get_text(GTK_LABEL(widget)), text) == 0) {
            for (GtkWidget *w = widget; w != NULL; w = gtk_widget_get_parent(w)) {
                if (GTK_IS_BUTTON(w))
                    return w;
            }
        }

        for (GtkWidget *child = gtk_widget_get_first_child(widget); child != NULL;
             child = gtk_widget_get_next_sibling(child)) {
            if (top < 512)
                stack[top++] = child;
        }
    }

    return NULL;
}

static gboolean
open_menu(gpointer data)
{
    gboolean submenu = GPOINTER_TO_INT(data);
    GtkWidget *button = find_type(window, GTK_TYPE_MENU_BUTTON);
    GtkWidget *popover = GTK_WIDGET(gtk_menu_button_get_popover(GTK_MENU_BUTTON(button)));

    gtk_popover_popup(GTK_POPOVER(popover));
    g_print("menu open\n");

    if (submenu) {
        GtkWidget *row = find_button(popover, "History");

        g_print("History item %s\n", row != NULL ? "found" : "MISSING");
        if (row != NULL)
            g_signal_emit_by_name(row, "clicked");
    }

    return G_SOURCE_REMOVE;
}

static void
activate(GtkApplication *application, gpointer data)
{
    (void)data;

    window = browser_window_new(application);
    gtk_window_present(GTK_WINDOW(window));
    g_timeout_add(900, open_menu, GINT_TO_POINTER(GPOINTER_TO_INT(data)));
}

int
main(int argc, char **argv)
{
    gboolean submenu = argc > 1 && g_strcmp0(argv[1], "history") == 0;

    GtkApplication *application = gtk_application_new("com.projectindigo.MenuProbe",
                                                      G_APPLICATION_NON_UNIQUE);
    g_signal_connect_data(application, "activate", G_CALLBACK(activate),
                          GINT_TO_POINTER(submenu), NULL, 0);

    char *app_argv[] = { argv[0], NULL };
    int status = g_application_run(G_APPLICATION(application), 1, app_argv);

    g_object_unref(application);
    return status;
}
